import {createEngine,stress,rebalance} from './engine.js';
const API_ORIGIN=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?'':'https://riskradar-aarohi.goofy-cedar-5467.chatgpt.site';
const $=id=>document.getElementById(id),money=v=>'$'+(v/1e6).toFixed(2)+'m';let signals=[],selected=null,timer=null,history=[];let polling=null;
const model=await fetch('model.json.gz').then(r=>{if(!r.ok)throw Error('Model could not load');return r.body.pipeThrough(new DecompressionStream('gzip'))}).then(stream=>new Response(stream).json());const [replay,portfolio]=await Promise.all(['replay','portfolio'].map(n=>fetch(n+'.json').then(r=>r.json())));const analyze=createEngine(model);const status=t=>$('status').textContent=t;
function add(rows){for(const row of rows){const s=row.sentiment_score!==undefined?row:analyze(row);if(!signals.some(x=>x.text===s.text&&x.source===s.source)){signals.push(s);history.push(rebalance(signals));selected=s}}render();status(`${signals.length} unique signals analyzed.`)}
function render(){const feed=$('feed');feed.replaceChildren();for(const s of [...signals].reverse()){const div=document.createElement('div');div.className='signal';const btn=document.createElement('button');btn.textContent=s.text;btn.onclick=()=>{selected=s;render()};const small=document.createElement('small');small.textContent=`${s.source} · ${s.company||'GLOBAL'} · ${s.event_classification} · ${s.synthetic?'synthetic replay':s.published_at||'manual input'}${s.low_confidence?' · low confidence':''}`;div.append(btn,small);if(s.url&&/^https?:\/\//.test(s.url)){const a=document.createElement('a');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Original source';a.style.fontSize='12px';div.append(a)}feed.append(div)}if(selected){$('sentiment').textContent=selected.sentiment_score.toFixed(2);$('sentiment').className=selected.sentiment_label;$('impact').textContent=selected.impact_score;$('event').textContent=selected.event_classification;$('json').textContent=JSON.stringify(selected,null,2);const t=+$('threshold').value,m=+$('multiplier').value;if(t<1||t>10||m<0||m>3){status('Threshold must be 1–10, multiplier 0–3.');return}const r=stress(selected,portfolio,t,m);$('before').textContent=money(r.before);$('after').textContent=money(r.after);$('loss').textContent=r.loss_pct.toFixed(2)+'%';$('trigger').textContent=r.triggered?'Stress triggered: illustrative adverse scenario':'No stress: impact does not exceed the threshold';$('assets').replaceChildren();for(const a of r.assets){const tr=document.createElement('tr');for(const v of [a.asset_type,money(a.before),money(a.after),money(a.change)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}$('assets').append(tr)}$('shock').textContent=`Shocks: equity ${(r.shock.equity*100).toFixed(1)}%, rates +${(r.shock.rates*100).toFixed(1)} percentage points, credit spread +${(r.shock.spread*100).toFixed(1)} percentage points.`}const weights=rebalance(signals);$('weights').replaceChildren();for(const w of weights){const row=document.createElement('div');row.className='bars';const name=document.createElement('span');name.textContent=w.ticker;const bar=document.createElement('div');bar.className='bar';bar.style.width=(w.weight/.2*100)+'%';const val=document.createElement('span');val.textContent=(w.weight*100).toFixed(2)+'%';row.append(name,bar,val);$('weights').append(row)}const svg=$('chart');svg.replaceChildren();for(const [ticker,color]of [['AAPL','#067b70'],['MSFT','#397bcc'],['TSLA','#bc3546']]){const line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('points',history.map((ws,i)=>`${30+i*440/Math.max(1,history.length-1)},${155-ws.find(w=>w.ticker===ticker).weight*700}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke',color);line.setAttribute('stroke-width','3');svg.append(line)}}
$('analyze').onclick=()=>{try{add([{text:$('text').value,company:$('company').value.toUpperCase(),source:$('source').value,published_at:new Date().toISOString(),synthetic:false}])}catch(e){status(e.message)}};
$('replay').onclick=()=>add(replay);$('reset').onclick=()=>{clearInterval(timer);timer=null;$('play').textContent='Play stream';signals=[];selected=null;history=[];render();for(const id of ['sentiment','impact','event','after','loss'])$(id).textContent='—';$('assets').replaceChildren();$('json').textContent='Choose a signal.';$('trigger').textContent='Select a signal to begin.';status('Reset complete.')};
$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='Play stream';return}let i=0;$('play').textContent='Pause stream';timer=setInterval(()=>{if(i>=replay.length){clearInterval(timer);timer=null;$('play').textContent='Play stream';return}add([replay[i++]]);},1500)};
for(const id of ['threshold','multiplier'])$(id).oninput=render;
$('upload').onchange=async e=>{try{const file=e.target.files[0];if(file.size>2000000)throw Error('File exceeds 2 MB');const rows=JSON.parse(await file.text());if(!Array.isArray(rows)||rows.some(r=>typeof r.text!=='string'))throw Error('Expected an array of objects containing text');add(rows.map(r=>({text:r.text,source:r.source||'import',company:r.company||'GLOBAL',published_at:r.published_at||'',synthetic:!!r.synthetic})))}catch(e){status(e.message)}};
$('fetch').onclick=async()=>{status('Fetching source…');try{const r=await fetch(API_ORIGIN+'/api/ingest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:$('live').value})});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('The live source API did not return JSON. Use the included local server if the service is unavailable.');const data=await r.json();if(!r.ok)throw Error(data.error);add(data)}catch(e){status(e.message)}};
$('poll').onclick=()=>{if(polling){clearInterval(polling);polling=null;$('poll').textContent='Start live polling (60s)';status('Live polling stopped.');return}const refresh=async()=>{for(const source of ['bbc','guardian']){try{const r=await fetch(API_ORIGIN+'/api/ingest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source})});const data=await r.json();if(!r.ok)throw Error(data.error);add(data)}catch(e){status(source+': '+e.message)}}};refresh();polling=setInterval(refresh,60000);$('poll').textContent='Stop live polling';};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({signals,weights:rebalance(signals),weight_history:history,stress:selected?stress(selected,portfolio,+$('threshold').value,+$('multiplier').value):null},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='riskradar-results.json';a.click();URL.revokeObjectURL(url)};render();status('Ready. Run replay or analyze your own text.');
